import { useId, type SVGProps } from 'react';

/**
 * Official, full-colour marks of the third-party tools Vireek integrates with.
 *
 * Sources (both CC0-1.0, trademarks remain the property of their owners):
 *  - simple-icons (HubSpot, Stripe, QuickBooks)
 *  - gilbarbara/logos via @iconify-json/logos (Google Calendar, Slack, Salesforce, Microsoft Teams)
 *
 * Marks are decorative: the accessible name is always rendered next to them by the caller,
 * so every SVG is aria-hidden. Gradient ids are made unique per instance with useId() because
 * the logo marquee renders each mark several times.
 *
 * ServiceTitan, Jobber, Housecall Pro and Microsoft 365 have no verified open-licence mark here.
 * They use <InitialMark /> until the official brand-kit SVG is supplied. Do not draw lookalikes.
 * Xero and WhatsApp are deliberately NOT here: their backends are not live-verified yet
 * (see XERO_SYNC.md and the header of whatsapp-webhook). Add them only after live verification.
 */
type MarkProps = Omit<SVGProps<SVGSVGElement>, 'viewBox' | 'children'>;

const BASE = {
  xmlns: 'http://www.w3.org/2000/svg',
  'aria-hidden': true,
  focusable: false,
} as const;

function uid(raw: string): string {
  return `vk${raw.replace(/[^a-zA-Z0-9]/g, '')}`;
}

