/**
 * Neutral placeholder for brands without a verified official mark. Tokens only.
 * The initial is painted by CSS (::before) so it never enters the DOM text: the visible
 * brand name next to it stays the only text of the link.
 */
export function InitialMark({ name }: { name: string }) {
  const initial = name.trim().charAt(0).toUpperCase();
  return (
    <span
      aria-hidden="true"
      data-initial={initial}
      className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-md bg-bg-tertiary text-xs font-bold text-text-secondary before:content-[attr(data-initial)]"
    />
  );
}
